'use strict';
/* Deterministic, fictional kitchen accounts. A rolling year: Nov 5, 2025–Nov 5,
 * 2026. 53 equal weekly invoices per customer; no seasonal demand adjustment.
 * All generated records retain demo provenance even after an ordinary edit. */
const DEMO_VERSION='v51',DEMO_START='2025-11-05',DEMO_END='2026-11-05';
function demoDataset(){
 const d={};DATA_LISTS.forEach(k=>d[k]=[]);
 const stamp=date=>Date.parse(date+'T12:00:00-05:00');
 const addDays=(date,n)=>{const x=new Date(date+'T12:00:00');x.setDate(x.getDate()+n);return dateString(x)};
 const row=(id,date,props,by='Brandon')=>({id:'demo-v51-'+id,demo:true,demoVersion:DEMO_VERSION,createdBy:by,by,createdAt:stamp(date),...props});
 d.products=[row('full-cord',DEMO_START,{name:'Seasoned hardwood — full cord',unit:'cord',price:330,cost:150,qty:42,cordsPerUnit:1}),row('face-cord',DEMO_START,{name:'Seasoned hardwood — face cord',unit:'face cord',price:115,cost:52,qty:24,cordsPerUnit:1/3}),row('delivery',DEMO_START,{name:'Kitchen delivery fee',unit:'delivery',price:35,cost:0,qty:0,cordsPerUnit:0}),row('stacking',DEMO_START,{name:'Wood-rack stacking service',unit:'service',price:15,cost:0,qty:0,cordsPerUnit:0})];
 const names=[['Ember Table Restaurant Group','Mara Ellison',330],['Cinder Lane Pizzeria','Theo Mercer',320],['Copper Oak Steakhouse','Ada Nolan',345],['Juniper Hearth Bakery','Eli Rowan',310],['Blue Ash Barbecue','Nina Vale',335],['Stonebridge Woodfire Bistro','Owen Reed',340],['Foxglove Flatbread Kitchen','Iris Finch',315],['Red Maple Chophouse','Luca Avery',350],['Willow & Flame Trattoria','Mae Collins',325],['Hearthstone Smoke Kitchen','Finn Sawyer',355]];
 names.forEach(([business,contact,price],n)=>d.accounts.push(row('customer-'+n,DEMO_START,{business,contact,phone:'616-555-01'+String(n).padStart(2,'0'),email:'receiving'+n+'@example.com',address:(100+n*24)+' Demo Market Way, Fictional Grand Rapids, MI',notes:'Kitchen receiving only. Keep seasoned hardwood dry and leave the loading lane clear. Fictional demonstration account.',usual:'Weekly seasoned hardwood: 1 full cord + delivery and rack stacking',priceNotes:'Contract full cord '+money(price)+' + $35 delivery + $15 stacking; steady weekly demand.',locations:'Main kitchen — rear receiving bay',terms:'Net 15',taxExemptNote:'Demo: 6% tax illustrated; actual tax treatment must be verified.',preferredDays:'Thursday, before lunch prep',prepaidCredit:0},n%2?'Billy':'Brandon')));
 Object.assign(d.accounts[0],{address:'180 Demo Foundry Lane, Fictional Grand Rapids, MI',locations:'Downtown grill — 180 Demo Foundry Lane, receiving dock A\nRiverside kitchen — 42 Demo Quay, side wood shed\nMarket hall — 7 Demo Arcade, loading bay 3',terms:'Net 30 · consolidated weekly billing',taxExemptNote:'DEMO resale certificate EX-DEMO-2026 on file; fictional exemption, verify eligibility and certificate before a real sale.',preferredDays:'Thursday 7–9 AM · weekly rotation across three kitchens',notes:'Contact Mara Ellison, group purchasing lead. Text receiving desk on arrival (demo instruction only). Rotate locations every week; keep each location’s rack labeled. One group invoice, location shown per delivery. No unattended drops.',usual:'1 full cord of seasoned oak/maple hardwood every week across the group',priceNotes:'$330 / full cord + $35 delivery + $15 stacking. Net-30 terms. 0% demo tax under fictional certificate.'});
 Object.assign(d.accounts[1],{address:'224 Demo Lantern Street, Fictional Grand Rapids, MI',locations:'Back door off Demo Lantern Alley · east wood rack',terms:'Prepaid credit reference · invoices remain separate',taxExemptNote:'Demo tax shown at 6%; verify actual kitchen use/exemption.',preferredDays:'Thursday 8–10 AM; Tuesday backup only',prepaidCredit:1250,notes:'Back-door gate code DEMO-2468. Enter from Lantern Alley, never through the dining room. Stack 16-inch seasoned hardwood on the covered east rack, bark facing out. Keep the fire exit clear. Call Theo before unloading. $1,250 prepaid credit tracked as a reference only; it is not automatically applied to invoices or added to cash.',usual:'1 full cord weekly; occasionally 3 face cords at the same contracted cord-equivalent price',priceNotes:'$320 / full cord + $35 delivery + $15 stacking. Prepaid balance is illustrative, not a real payment.'});
 let num=5101;
 for(let week=0;week<53;week++)for(let n=0;n<10;n++){
  const a=d.accounts[n],price=names[n][2],date=addDays(DEMO_START,week*7),deliveryDate=addDays(date,1),delivered=deliveryDate<DEMO_END;
  const useFace=price%3===0&&(week+n)%8===3,location=n===0?a.locations.split('\n')[week%3]:a.locations;
  const paid=!(n===0&&week>=49)&&!(n!==0&&week===52)&&!([1,4,7].includes(n)&&week===46);
  const paidDate=addDays(date,Math.min(n===0?21:7,Math.floor((stamp(DEMO_END)-stamp(date))/864e5)));
  d.invoices.push(row('invoice-'+week+'-'+n,date,{num:num++,accountId:a.id,date,dueDate:addDays(date,n===0?30:15),deliveryDate,deliveryLocation:location,lines:[{pid:d.products[useFace?1:0].id,name:'Seasoned hardwood — '+(useFace?'face cord':'full cord')+' ('+(useFace?'face cord':'cord')+')',qty:useFace?3:1,price:useFace?price/3:price},{pid:d.products[2].id,name:'Kitchen delivery fee',qty:1,price:35},{pid:d.products[3].id,name:'Wood-rack stacking service',qty:1,price:15}],taxRate:n===0?0:6,paid,paidAt:paid?stamp(paidDate):null,delivered,deliveredDate:delivered?deliveryDate:null,deliveredBy:delivered?(week%2?'Billy':'Brandon'):null,note:'DEMO — not an actual charge. Weekly kitchen supply · '+location+(n===0?' · Net 30, fictional resale certificate on file.':n===1?' · Back door, covered east rack. Credit reference in customer profile.':' · Keep fire exits clear.')},week%2?'Billy':'Brandon'));
  d.mileage.push(row('trip-'+week+'-'+n,deliveryDate,{date:deliveryDate,accountId:a.id,purpose:businessRoute(a.business,location),miles:12+n*2+(week%3),rate:deliveryDate<'2026-01-01'?.70:deliveryDate<'2026-07-01'?.725:.76,partner:week%2?'Billy':'Brandon'},week%2?'Billy':'Brandon'));
 }
 // Actual ledger transactions, evenly distributed across the full rolling year.
 for(let m=0;m<13;m++){
  const x=new Date(2025,10+m,1),month=monthKey(x),day=m===0?'06':m===12?'03':'10',date=month+'-'+day;
  const purchases=[['fuel','Fuel','Route diesel',159.60,true,true],['saw','Supplies','Chainsaw sharpening & chains',92+(m%3)*12,true,false],['splitter','Supplies','Log splitter hydraulic service',85+(m%2)*35,true,false],['truck','Vehicle','Delivery truck upkeep',120+(m%4)*25,true,true],['wood','Inventory purchase','Seasoned hardwood log supply',5700,false,false]];
  for(const [id,category,vendor,amount,deductible,vehicleRelated]of purchases)d.expenses.push(row('expense-'+m+'-'+id,date,{date,category,vendor:vendor+' · Demo',amount,deductible,vehicleRelated,note:'Fictional operating cost. '+(id==='wood'?'Inventory purchases are not automatically deducted by this simplified tax model.':'Kitchen delivery operation.'),receipt:null},m%2?'Billy':'Brandon'));
  d.events.push(row('monthly-check-'+m,date,{date,title:'Kitchen route & stock review · Demo',kind:'task',amount:0,done:date<DEMO_END,note:'Check dry covered stock, truck straps, restaurant rack capacity and receiving windows.'}));
  for(const partner of ['Brandon','Billy'])d.equity.push(row('draw-'+m+'-'+partner,date,{date,partner,kind:'Draw',amount:650,note:'Demo monthly partner draw; not a tax deduction.'},partner));
 }
 const fuel=d.expenses.find(e=>e.id==='demo-v51-expense-11-fuel');fuel.date='2026-10-29';fuel.accountId=d.accounts[1].id;fuel.note='Cinder Lane Pizzeria delivery route fuel. See customer instructions and mileage log. Fictional receipt attached.';fuel.receipt={name:'demo-route-receipt.jpg',type:'image/jpeg',data:DEMO_RECEIPT};
 for(const [n,date,amount]of [[0,'2026-01-20',1400],[1,'2026-04-20',1600],[2,'2026-07-20',1600],[3,'2026-10-20',1600]])d.expenses.push(row('sales-remit-'+n,date,{date,category:'Sales tax remittance',vendor:'Demo sales tax remittance',amount,deductible:false,vehicleRelated:false,note:'Fictional remittance; not an income-tax deduction.'}));
 d.assets=[row('opening-bank','2025-11-04',{name:'Demo opening business bank',type:'Cash / bank',cost:18000,date:'2025-11-04',life:0,salvage:0,cashPurchase:false,deductible:false}),row('truck',DEMO_START,{name:'Demo delivery truck',type:'Vehicle',cost:32000,date:DEMO_START,life:5,salvage:8000,cashPurchase:true,deductible:true}),row('trailer',DEMO_START,{name:'Demo tandem-axle trailer',type:'Trailer',cost:8500,date:DEMO_START,life:8,salvage:1500,cashPurchase:true,deductible:true}),row('splitter',DEMO_START,{name:'Demo hydraulic log splitter',type:'Equipment',cost:4200,date:DEMO_START,life:7,salvage:700,cashPurchase:true,deductible:true})];
 for(const partner of ['Brandon','Billy'])d.equity.unshift(row('contribution-'+partner,DEMO_START,{date:DEMO_START,partner,kind:'Contribution',amount:10000,note:'Demo startup contribution; separate from opening bank balance.'},partner));
 d.liabilities=[row('truck-loan',DEMO_START,{name:'Demo equipment loan',date:DEMO_START,balance:12000,cashReceived:15000,cashRepaid:3000})];
 d.projects=[row('project','2026-10-01',{name:'Kitchen route rack-label rollout · Demo',progress:70,next:'Finish location labels at Ember Table Market Hall, then confirm Cinder Lane back-door checklist.',due:'2026-11-19',complete:false})];
 d.goals=[row('goal-revenue',DEMO_START,{name:'Annual kitchen revenue · Demo',kind:'revenue',target:205000,current:0,start:DEMO_START,end:DEMO_END,complete:false}),row('goal-cords',DEMO_START,{name:'Weekly kitchen cord supply · Demo',kind:'cords',target:530,current:0,start:DEMO_START,end:DEMO_END,complete:false}),row('goal-racks',DEMO_START,{name:'Kitchen receiving checklists · Demo',kind:'custom',target:10,current:7,start:DEMO_START,end:'2026-11-30',complete:false})];
 // Recurring weekly reminders are plans, not duplicate invoices or revenue.
 for(let week=0;week<4;week++)for(const n of [0,1]){const date=addDays(DEMO_END,week*7),a=d.accounts[n];d.events.push(row('recurring-'+week+'-'+n,date,{date,kind:'delivery',title:'Weekly kitchen delivery · '+a.business,done:false,amount:0,accountId:a.id,note:'DEMO recurring weekly plan, not an additional charge. '+(n===0?a.locations.split('\n')[week%3]+' · Net 30':a.preferredDays+' · Back door, covered east rack. Prepaid credit reference $1,250.')}))}
 d.feedback=[row('revision','2026-11-02',{title:'Cinder Lane prepaid credit & receiving · Demo',body:'Demo walkthrough: check Cinder Lane’s $1,250 reference credit before billing. Show Theo’s back-door instructions, east stacking rack and Thursday preference to the driver. The related Oct 29 fuel expense has a demo receipt photo; mileage is linked to this kitchen. Credit does not auto-apply or change cash in this release.',status:'Discussing'},'Billy')];
 d.stockLog=d.products.filter(p=>p.cordsPerUnit).map(p=>row('stock-'+p.id,DEMO_START,{at:stamp(DEMO_START),pid:p.id,name:p.name,delta:p.qty,reason:'Demo opening stock'}));
 d.activity=[row('activity','2026-11-02',{at:stamp('2026-11-02'),entity:'feedback',recordId:d.feedback[0].id,action:'Added',name:d.feedback[0].title},'Billy')];
 return d;
}
function businessRoute(name,location){return name+' · kitchen hardwood delivery · '+location}
function appendDemoData(){const demo=demoDataset();for(const k of DATA_LISTS)D[k].push(...demo[k]);D.currentProjectId=D.currentProjectId||demo.projects[0].id;D.demoInitializedV51=true;D.nextInvoice=Math.max(+D.nextInvoice||1001,...D.invoices.map(i=>(+i.num||0)+1));}
function removeDemoRecords(){const ids=new Set(DATA_LISTS.flatMap(k=>D[k].filter(r=>r.demo===true||r.demoVersion===DEMO_VERSION||String(r.id||'').startsWith('demo-v51-')).map(r=>r.id)).filter(Boolean));for(const k of DATA_LISTS)D[k]=D[k].filter(r=>r.demo!==true&&r.demoVersion!==DEMO_VERSION&&!String(r.id||'').startsWith('demo-v51-')&&!ids.has(r.recordId)&&!ids.has(r.pid));if(!D.projects.some(p=>p.id===D.currentProjectId))D.currentProjectId=(D.projects.find(p=>!p.complete)||{}).id||null;D.demoInitializedV51=true;}
function loadDemoData(){if(!confirm('Load the fictional kitchen demo? Existing demo records (including edited demo records) will be replaced. Your own records stay. Export a backup first.'))return;removeDemoRecords();appendDemoData();initializeAudit();save();render()}
function removeDemoData(){if(!confirm('Remove all demo records, including edits to demo records? Your own records stay, but links to removed demo customers/products will no longer resolve. Export a backup first.'))return;removeDemoRecords();D.cleanupNotice=null;initializeAudit();save();render()}

const DEMO_RECEIPT='data:image/jpeg;base64,';
